using System;using System.Data.SqlClient;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Core { public static class InsuranceService {
 public static InsuranceClaim Calculate(int saleId,PatientProfile patient,decimal gross,decimal coveragePercent){if(patient==null)throw new ArgumentNullException("patient");if(coveragePercent<0||coveragePercent>100)throw new ArgumentOutOfRangeException("coveragePercent");var covered=Math.Round(gross*coveragePercent/100m,0);return new InsuranceClaim{SaleId=saleId,PatientId=patient.Id,Provider=patient.Insurance,PolicyNo=patient.InsuranceNo,GrossAmount=gross,CoveredAmount=covered,PatientShare=gross-covered,Status="Draft"};}
 public static void Save(InsuranceClaim x){if(!Database.IsAvailable||x==null)return;using(var c=Database.Open())using(var q=new SqlCommand("INSERT INTO dbo.InsuranceClaims(SaleId,PatientId,Provider,PolicyNo,GrossAmount,CoveredAmount,PatientShare,Status,CreatedAt) VALUES(@s,@p,@v,@n,@g,@c,@ps,@st,SYSUTCDATETIME())",c)){q.Parameters.AddWithValue("@s",x.SaleId);q.Parameters.AddWithValue("@p",x.PatientId);q.Parameters.AddWithValue("@v",(object)x.Provider??DBNull.Value);q.Parameters.AddWithValue("@n",(object)x.PolicyNo??DBNull.Value);q.Parameters.AddWithValue("@g",x.GrossAmount);q.Parameters.AddWithValue("@c",x.CoveredAmount);q.Parameters.AddWithValue("@ps",x.PatientShare);q.Parameters.AddWithValue("@st",x.Status);q.ExecuteNonQuery();}}
 } }